class FK:
    def __init__(self,n):
        self.table=[[0]*n for i in range(n)]
        self.n=n

    def add(self,x,y,f):
        self.table[x][y]=f

    def ford(self,s,t,f):
        self.visit[s]=True
        if s==t:
            return f
        for i in range(self.n):
